"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[915],{9902:(e,a,o)=>{o.d(a,{C:()=>s,IB:()=>t,Zd:()=>i,pg:()=>r,zl:()=>n});let t=["en","es","fr"],n="soda-locale";function i(e){return null!=e&&t.includes(e)}function r(){let e=arguments.length>0&&void 0!==arguments[0]?arguments[0]:[];for(let a of e){let e=a.trim().toLowerCase().split(/[-_]/)[0];if("en"===e||"es"===e||"fr"===e)return e}return"en"}let s={en:{metaDescription:"A Design Challenge in collaboration with Fab Lab Barcelona and OCAD University",season:"2026 – 2027 (pilot)",hook:["Creativity","Curiosity","Collaboration"],collaboration:"In Collaboration With",discover:"Discover",join:"Join the challenge",joinLine1:"Join the",joinLine2:"challenge",becomeLine1:"Become a",becomeLine2:"Partner",becomeLabel:"Become a Partner",menu:"Menu",openMenu:"Open menu",closeMenu:"Close menu",navCriteria:"Criteria",navSchedule:"Schedule",involved:"Get involved",language:"Language",scrollMore:"Scroll for more",soda:{kicker:"What is SOD+A?",title:"Schools of Discovery + Action",body:"SOD+A stands for Schools of Discovery + Action. It is an international design challenge for high school students where they explore ideas through creative uses of technology, share knowledge and collaborate with students in other communities, then bring their different skills and discoveries together to co-design a project that makes a lasting contribution locally.",quote:"You may be working locally, but knowledge is global."},involve:{kicker:"How to Participate",title:"Connecting Students to the Challenge",pilot:"This pilot year, participation is by invite, or you can reach out using one of the forms on this page.",body:"Participating schools and labs have a facilitator, teacher, coach, or mentor to help a student group take part in the SOD+A Challenge, encouraging them to iterate, experiment, share, and document their creations and attempts on our global board. Participating schools and labs also help connect students to co-design opportunities where their newly discovered skills can be put into action to make a difference.",examplesTitle:"From last year",examples:[{id:"bennett",name:"Bennett"},{id:"sofia",name:"Sofia"},{id:"theo",name:"Theo"},{id:"abby",name:"Abby"}]},glance:{leadTitle:"Learn across borders",lead:"Share your process with students in other communities, remake and adapt each other's work, and build relationships through making.",fitTitle:"How it fits",fit:"Run SOD+A as a co-curricular activity, a class, or a collaboration with another organization. Your group chooses the format and can use the frameworks it already knows. Projects can build on work students are already doing for other school initiatives.",timelineTitle:"Timeline",timeline:"Four key dates between September and May, with deadlines, showcases, and group meetups. Smaller shared moments may happen in between.",whoTitle:"Who can join",who:"Students aged 14-18 working with a school, a makerspace, or another organization. No Fab Lab is needed. Any level of technology is welcome, from simple hand tools to laser cutters and code.",bringTitle:"Participating Schools & Labs",bring:"Include a facilitator who runs the group, such as a teacher, coach, or mentor. Student access to computers, tools or fabrication machines, and craft supplies. A project students co-design to make an impact. A willingness to share your process, such as a file, a recipe, or a series of steps, so others can remake, learn from, and adapt your work. Investment of enough time to iterate, respond to feedback, and showcase your efforts.",providesTitle:"SOD+A provides",provides:"The structure facilitators need to get started, including prompts, criteria, best practices, and four key dates for deliverables and feedback. A global board for sharing, and regular group check-ins to compare notes and ask questions. No cost to join this pilot year."},schools:{kicker:"Participating schools & labs"},challenge:{kicker:"What is the challenge?",title:"See how far you can push an idea",intro:"It can be exciting to think of something you'd love to make. Sometimes you don't know where to start or how to use your skills to contribute to your community. Either way, the challenge is turning ideas into meaningful action. That is what SOD+A stands for, moving from discovery to action.",beats:[{title:"Discover.",detail:"Instead of a big, defined project, we add a twist. Bring an interest or start from scratch, let the randomly drawn prompts guide you somewhere new, experiment, share what you learn, and see what happens."},{title:"Act.",detail:"Now you have new ideas and new skills. Put them to work with friends and your school. Work as a team to bring positive change to a community through design. Document it for the world to see."}],closeBefore:"Scroll to the ",closeLink:"criteria",closeAfter:" to see what to aim for..."},who:{kicker:"Who is it for?",title:"Students who want to make things with others",body:"SOD+A is for students aged 14-18 in schools, makerspaces, or Fab Labs interested in creative engineering, entrepreneurship, digital and product design, media, creative direction, project management, art and technology, or any field where ideas, initiative, collaboration, and community engagement matter."},why:{kicker:"Why?",title:"The other side of innovation",p1:"School gives you knowledge, skills, and structure. SOD+A gives you the experience of learning through design and community. Hands-on, collaborative discovery that's common in Fab Labs and universities but doesn't always fit into a high school curriculum. Working alongside students, Fab Labs, and universities beyond your own school, you'll dive deeper into what you're curious about, use technology to make something meaningful, and build the many skills the world needs, including creativity, curiosity, resilience, judgment, and collaboration.",p2:"Along the way, you build a portfolio that makes your process, decisions, and growth visible, while receiving feedback and recognition from partner schools and organizations that value these skills. It is a chance to get noticed while having fun, discovering what you can do, and learning what it means to bring your talents into the world."},criteria:{kicker:"Challenge criteria",title:"Show us what you can do",intro:"Partner institutions set the criteria. Meeting them leads to levels, achievements, and certificates as you experiment, document, and share."},schedule:{kicker:"Schedule",title:"September to May",intro:"The pilot year, marked on one line. Rest on a dot to read that date.",months:["September","November","February","May"]},joinForm:{title:"Join the challenge",intro:"Want to participate in the SOD+A Challenge? Fill this form:",studentChoice:"I am a student",facilitatorChoice:"I am a facilitator",studentIntro:["Students are guided through the challenge by a facilitator, a teacher, coach, or mentor who helps them get started.","If you heard about this challenge and want to get involved, and would like your school or friends to join, fill out this form and we will do our best to help you form a group or join one."],facilitatorIntro:["We recognize and celebrate the many ways schools, clubs, labs, and organizations are already integrating design, making, and creativity into youth experiences or curriculum. SOD+A doesn't replace what you do; it amplifies and supports it, adding a community and platform for global sharing and student motivation. We're working to build an international network of schools, Fab Labs, and universities to encourage divergent thinking and sharing across communities, and we simply want to join forces, introduce students to incredible creative things happening around the world, and challenge them to take creative risks and learn from each other.","Facilitators need access to a creative space where students can share work and ideas, but you don't need a Fab Lab or special technology. Where possible, we can help you find a makerspace or Fab Lab, or work with you to plan and program SOD+A into your current context. In short, we want creative energy, curiosity, and collaboration over complexity and large installations full of technology. We can support you through the structure and pacing of the SOD+A Challenge no matter how many resources you have access to, but it's the human part that matters most."],submit:"Send",sending:"Sending…",thanks:"Thank you. We will be in touch.",error:"Couldn't send. Try again, or email hello@sodachallenge.org.",activate:"Check Gmail for an email from FormSubmit, click Activate Form, then send again.",back:"Back to the challenge",name:"Name",email:"Email",age:"Age",schoolLevel:"School level",schoolOrg:"School or organization",guideName:"Name of a teacher or professional who can guide you",guideEmail:"Their email",interests:"Interests",orgName:"Name of organization",role:"Role",studentAges:"Age of students you work with",facilities:"Facilities you have access to",expertise:"Expertise in your organization that can help?",questions:"Any questions about the challenge?",hours:"How many hours a week can you cover for this activity?"},ask:{kicker:"The bigger picture",paragraphs:["Our goal is to grow SOD+A as an international showcase that celebrates student action toward creativity, curiosity, and collaboration. We want to challenge students to engage in the kinds of experiences that build these skills, and to offer real feedback from the world that needs them.","Currently the SOD+A Challenge is a concept in action. We tested the idea last year with two schools and two partners, and saw students get excited to experiment, iterate, share, and act on their ideas through design. We are now looking at a second pilot year to expand on this, and co-designing the experience with our participants and partners."]},reach:{mapLabel:"World map of Schools of Discovery + Action",cities:{montreal:"Montreal",barcelona:"Barcelona",toronto:"Toronto",calgary:"Calgary",monterey:"Monterey"},places:{montreal:"Lower Canada College",barcelona:"Fab Lab Barcelona",toronto:"OCAD University",calgary:"",monterey:"Mexico"}}},fr:{metaDescription:"Un d\xe9fi de design en collaboration avec Fab Lab Barcelona et OCAD University",season:"2026 – 2027 (pilote)",hook:["Cr\xe9ativit\xe9","Curiosit\xe9","Collaboration"],collaboration:"En collaboration avec",discover:"D\xe9couvrir",join:"Rejoindre le d\xe9fi",joinLine1:"Rejoindre",joinLine2:"le d\xe9fi",becomeLine1:"Devenir",becomeLine2:"partenaire",becomeLabel:"Devenir partenaire",menu:"Menu",openMenu:"Ouvrir le menu",closeMenu:"Fermer le menu",navCriteria:"Crit\xe8res",navSchedule:"Calendrier",involved:"Participer",language:"Langue",scrollMore:"Continuer vers le bas",soda:{kicker:"Qu'est-ce que SOD+A ?",title:"Schools of Discovery + Action",body:"SOD+A signifie Schools of Discovery + Action (\xe9coles de d\xe9couverte + action). C'est un d\xe9fi international de design pour les \xe9l\xe8ves du secondaire : ils explorent des id\xe9es par des usages cr\xe9atifs de la technologie, partagent leurs connaissances et collaborent avec des \xe9l\xe8ves d'autres communaut\xe9s, puis rassemblent leurs comp\xe9tences et d\xe9couvertes pour co-concevoir un projet qui laisse une contribution durable \xe0 l'\xe9chelle locale.",quote:"Vous travaillez peut-\xeatre \xe0 l'\xe9chelle locale, mais le savoir est mondial."},involve:{kicker:"Comment participer",title:"Relier les \xe9l\xe8ves au d\xe9fi",pilot:"Cette ann\xe9e pilote, la participation se fait sur invitation, ou vous pouvez nous joindre avec l'un des formulaires de cette page.",body:"Les \xe9coles et labs participants ont un facilitateur, un enseignant, un coach ou un mentor pour aider un groupe d'\xe9l\xe8ves \xe0 prendre part au d\xe9fi SOD+A, en les encourageant \xe0 it\xe9rer, exp\xe9rimenter, partager et documenter leurs cr\xe9ations et leurs essais sur notre tableau global. Les \xe9coles et labs participants aident aussi \xe0 relier les \xe9l\xe8ves \xe0 des occasions de co-conception o\xf9 leurs comp\xe9tences nouvellement d\xe9couvertes peuvent \xeatre mises en action pour faire une diff\xe9rence.",examplesTitle:"L'an dernier",examples:[{id:"bennett",name:"Bennett"},{id:"sofia",name:"Sofia"},{id:"theo",name:"Theo"},{id:"abby",name:"Abby"}]},glance:{leadTitle:"Apprendre \xe0 travers les fronti\xe8res",lead:"Partagez votre processus avec des \xe9l\xe8ves d'autres communaut\xe9s, refaites et adaptez le travail les uns des autres, et tissez des liens en fabriquant.",fitTitle:"Comment \xe7a s'int\xe8gre",fit:"Menez SOD+A comme une activit\xe9 cocurriculaire, un cours, ou une collaboration avec une autre organisation. Votre groupe choisit le format et peut utiliser les cadres qu'il conna\xeet d\xe9j\xe0. Les projets peuvent s'appuyer sur le travail que les \xe9l\xe8ves font d\xe9j\xe0 pour d'autres initiatives de l'\xe9cole.",timelineTitle:"Calendrier",timeline:"Quatre dates cl\xe9s entre septembre et mai, avec des \xe9ch\xe9ances, des pr\xe9sentations et des rencontres de groupe. De plus petits moments partag\xe9s peuvent avoir lieu entre les deux.",whoTitle:"Qui peut participer",who:"Des \xe9l\xe8ves de 14 \xe0 18 ans qui travaillent avec une \xe9cole, un espace de fabrication, ou une autre organisation. Un Fab Lab n'est pas n\xe9cessaire. Tout niveau de technologie est le bienvenu, des outils \xe0 main simples aux d\xe9coupeuses laser et au code.",bringTitle:"\xc9coles et labs participants",bring:"Incluez un facilitateur qui anime le groupe, comme un enseignant, un coach ou un mentor. Un acc\xe8s des \xe9l\xe8ves \xe0 des ordinateurs, des outils ou des machines de fabrication, et du mat\xe9riel d'artisanat. Un projet que les \xe9l\xe8ves co-con\xe7oivent pour avoir un impact. Une volont\xe9 de partager votre processus, comme un fichier, une recette ou une s\xe9rie d'\xe9tapes, pour que d'autres puissent refaire votre travail, en tirer des le\xe7ons et l'adapter. L'investissement du temps n\xe9cessaire pour it\xe9rer, r\xe9pondre aux commentaires et pr\xe9senter vos efforts.",providesTitle:"SOD+A fournit",provides:"La structure dont les facilitateurs ont besoin pour commencer, y compris des consignes, des crit\xe8res, des bonnes pratiques et quatre dates cl\xe9s pour les livrables et les retours. Un tableau global pour partager, et des points r\xe9guliers en groupe pour comparer les notes et poser des questions. Aucun co\xfbt pour rejoindre cette ann\xe9e pilote."},schools:{kicker:"\xc9coles et labs participants"},challenge:{kicker:"Quel est le d\xe9fi ?",title:"Voyez jusqu'o\xf9 vous pouvez pousser une id\xe9e",intro:"Il peut \xeatre passionnant de penser \xe0 quelque chose que vous aimeriez fabriquer. Parfois, vous ne savez pas par o\xf9 commencer, ni comment utiliser vos comp\xe9tences pour contribuer \xe0 votre communaut\xe9. Dans un cas comme dans l'autre, le d\xe9fi est de transformer des id\xe9es en action porteuse de sens. C'est ce que signifie SOD+A, passer de la d\xe9couverte \xe0 l'action.",beats:[{title:"D\xe9couvrez.",detail:"Au lieu d'un grand projet d\xe9fini, nous ajoutons un d\xe9tour. Apportez un int\xe9r\xeat ou partez de z\xe9ro, laissez les consignes tir\xe9es au hasard vous guider vers quelque chose de nouveau, exp\xe9rimentez, partagez ce que vous apprenez, et voyez ce qui se passe."},{title:"Agissez.",detail:"Vous avez maintenant de nouvelles id\xe9es et de nouvelles comp\xe9tences. Mettez-les au travail avec des amis et votre \xe9cole. Travaillez en \xe9quipe pour apporter un changement positif \xe0 une communaut\xe9 par le design. Documentez-le pour que le monde le voie."}],closeBefore:"Faites d\xe9filer jusqu'aux ",closeLink:"crit\xe8res",closeAfter:" pour voir quoi viser..."},who:{kicker:"Pour qui ?",title:"Des \xe9l\xe8ves qui veulent cr\xe9er avec d'autres",body:"SOD+A s'adresse aux \xe9l\xe8ves de 14 \xe0 18 ans, dans les \xe9coles, makerspaces ou Fab Labs, int\xe9ress\xe9s par l'ing\xe9nierie cr\xe9ative, l'entrepreneuriat, le design num\xe9rique et de produit, les m\xe9dias, la direction cr\xe9ative, la gestion de projet, l'art et la technologie, ou tout domaine o\xf9 comptent les id\xe9es, l'initiative, la collaboration et l'engagement communautaire."},why:{kicker:"Pourquoi ?",title:"L'autre c\xf4t\xe9 de l'innovation",p1:"L'\xe9cole vous donne des connaissances, des comp\xe9tences et une structure. SOD+A vous donne l'exp\xe9rience d'apprendre par le design et la communaut\xe9. Une d\xe9couverte collaborative et concr\xe8te, courante dans les Fab Labs et les universit\xe9s, qui n'entre pas toujours dans un programme de secondaire. Aux c\xf4t\xe9s d'\xe9l\xe8ves, de Fab Labs et d'universit\xe9s au-del\xe0 de votre propre \xe9cole, vous irez plus au fond de ce qui \xe9veille votre curiosit\xe9, utiliserez la technologie pour cr\xe9er quelque chose de porteur de sens, et d\xe9velopperez les nombreuses comp\xe9tences dont le monde a besoin, dont la cr\xe9ativit\xe9, la curiosit\xe9, la r\xe9silience, le jugement et la collaboration.",p2:"En chemin, vous construisez un portfolio qui rend visibles votre processus, vos d\xe9cisions et votre progression, tout en recevant des commentaires et une reconnaissance d'\xe9coles et d'organisations partenaires qui valorisent ces comp\xe9tences. C'est une chance d'\xeatre vu, de s'amuser, de d\xe9couvrir ce que vous pouvez faire, et d'apprendre ce que signifie porter vos talents dans le monde."},criteria:{kicker:"Crit\xe8res du d\xe9fi",title:"Montrez-nous ce que vous pouvez faire",intro:"Les institutions partenaires d\xe9finissent les crit\xe8res. Les remplir ouvre des niveaux, des accomplissements et des certificats, pendant que vous exp\xe9rimentez, documentez et partagez."},schedule:{kicker:"Calendrier",title:"De septembre \xe0 mai",intro:"L'ann\xe9e pilote, marqu\xe9e sur une ligne. Restez sur un point pour lire cette date.",months:["Septembre","Novembre","F\xe9vrier","Mai"]},joinForm:{title:"Rejoindre le d\xe9fi",intro:"Vous voulez participer au d\xe9fi SOD+A ? Remplissez ce formulaire :",studentChoice:"Je suis \xe9l\xe8ve",facilitatorChoice:"Je suis facilitateur/facilitatrice",studentIntro:["Les \xe9l\xe8ves sont guid\xe9s dans le d\xe9fi par un facilitateur, un enseignant, un coach ou un mentor qui les aide \xe0 d\xe9marrer.","Si vous avez entendu parler de ce d\xe9fi et voulez vous impliquer, et que vous aimeriez que votre \xe9cole ou vos amis participent, remplissez ce formulaire et nous ferons de notre mieux pour vous aider \xe0 former un groupe ou \xe0 en rejoindre un."],facilitatorIntro:["Nous reconnaissons et c\xe9l\xe9brons les nombreuses fa\xe7ons dont les \xe9coles, les clubs, les labs et les organisations int\xe8grent d\xe9j\xe0 le design, le faire et la cr\xe9ativit\xe9 dans les exp\xe9riences ou les programmes des jeunes. SOD+A ne remplace pas ce que vous faites ; il l'amplifie et le soutient, en ajoutant une communaut\xe9 et une plateforme pour le partage mondial et la motivation des \xe9l\xe8ves. Nous travaillons \xe0 b\xe2tir un r\xe9seau international d'\xe9coles, de Fab Labs et d'universit\xe9s pour encourager la pens\xe9e divergente et le partage entre communaut\xe9s, et nous voulons simplement unir nos forces, faire d\xe9couvrir aux \xe9l\xe8ves les choses cr\xe9atives extraordinaires qui se passent dans le monde, et les mettre au d\xe9fi de prendre des risques cr\xe9atifs et d'apprendre les uns des autres.","Les facilitateurs ont besoin d'acc\xe8s \xe0 un espace cr\xe9atif o\xf9 les \xe9l\xe8ves peuvent partager leur travail et leurs id\xe9es, mais vous n'avez pas besoin d'un Fab Lab ni d'une technologie particuli\xe8re. Quand c'est possible, nous pouvons vous aider \xe0 trouver un makerspace ou un Fab Lab, ou travailler avec vous pour planifier et int\xe9grer SOD+A dans votre contexte actuel. En bref, nous voulons de l'\xe9nergie cr\xe9ative, de la curiosit\xe9 et de la collaboration, plut\xf4t que de la complexit\xe9 et de grandes installations pleines de technologie. Nous pouvons vous accompagner dans la structure et le rythme du d\xe9fi SOD+A, quels que soient les moyens dont vous disposez, mais c'est la part humaine qui compte le plus."],submit:"Envoyer",sending:"Envoi…",thanks:"Merci. Nous reviendrons vers vous.",error:"L'envoi a \xe9chou\xe9. R\xe9essayez, ou \xe9crivez \xe0 hello@sodachallenge.org.",activate:"V\xe9rifiez Gmail, ouvrez le courriel de FormSubmit, cliquez sur Activate Form, puis renvoyez.",back:"Retour au d\xe9fi",name:"Nom",email:"Courriel",age:"\xc2ge",schoolLevel:"Niveau scolaire",schoolOrg:"\xc9cole ou organisation",guideName:"Nom d'un enseignant ou d'un professionnel qui peut vous accompagner",guideEmail:"Son courriel",interests:"Int\xe9r\xeats",orgName:"Nom de l'organisation",role:"R\xf4le",studentAges:"\xc2ge des \xe9l\xe8ves avec qui vous travaillez",facilities:"Installations auxquelles vous avez acc\xe8s",expertise:"Quelle expertise dans votre organisation peut aider ?",questions:"Des questions sur le d\xe9fi ?",hours:"Combien d'heures par semaine pouvez-vous consacrer \xe0 cette activit\xe9 ?"},ask:{kicker:"Le tableau d'ensemble",paragraphs:["Notre objectif est de faire grandir SOD+A comme vitrine internationale qui c\xe9l\xe8bre l'action des \xe9l\xe8ves vers la cr\xe9ativit\xe9, la curiosit\xe9 et la collaboration. Nous voulons mettre les \xe9l\xe8ves au d\xe9fi de vivre le genre d'exp\xe9riences qui construisent ces comp\xe9tences, et leur offrir de vrais retours du monde qui en a besoin.","Actuellement, le SOD+A Challenge est un concept en action. Nous avons test\xe9 l'id\xe9e l'an dernier avec deux \xe9coles et deux partenaires, et nous avons vu des \xe9l\xe8ves s'enthousiasmer pour exp\xe9rimenter, it\xe9rer, partager et agir sur leurs id\xe9es par le design. Nous envisageons maintenant une deuxi\xe8me ann\xe9e pilote pour aller plus loin, et nous co-concevons l'exp\xe9rience avec nos participants et nos partenaires."]},reach:{mapLabel:"Carte du monde des Schools of Discovery + Action",cities:{montreal:"Montr\xe9al",barcelona:"Barcelone",toronto:"Toronto",calgary:"Calgary",monterey:"Monterey"},places:{montreal:"Lower Canada College",barcelona:"Fab Lab Barcelona",toronto:"OCAD University",calgary:"",monterey:"Mexique"}}},es:{metaDescription:"Un reto de dise\xf1o en colaboraci\xf3n con Fab Lab Barcelona y OCAD University",season:"2026 – 2027 (piloto)",hook:["Creatividad","Curiosidad","Colaboraci\xf3n"],collaboration:"En colaboraci\xf3n con",discover:"Descubre",join:"\xdanete al reto",joinLine1:"\xdanete al",joinLine2:"reto",becomeLine1:"Hazte",becomeLine2:"aliado",becomeLabel:"Hazte aliado",menu:"Men\xfa",openMenu:"Abrir men\xfa",closeMenu:"Cerrar men\xfa",navCriteria:"Criterios",navSchedule:"Calendario",involved:"Participa",language:"Idioma",scrollMore:"Sigue bajando",soda:{kicker:"\xbfQu\xe9 es SOD+A?",title:"Schools of Discovery + Action",body:"SOD+A significa Schools of Discovery + Action (Escuelas de Descubrimiento + Acci\xf3n). Es un reto internacional de dise\xf1o para estudiantes de secundaria en el que exploran ideas a trav\xe9s de usos creativos de la tecnolog\xeda, comparten conocimiento y colaboran con estudiantes de otras comunidades, y luego re\xfanen distintas habilidades y descubrimientos para co-dise\xf1ar un proyecto que deje una contribuci\xf3n duradera en lo local.",quote:"Puedes estar trabajando en lo local, pero el conocimiento es global."},involve:{kicker:"C\xf3mo participar",title:"Conectar a los estudiantes con el reto",pilot:"Este a\xf1o piloto, la participaci\xf3n es por invitaci\xf3n, o puedes escribirnos con uno de los formularios de esta p\xe1gina.",body:"Las escuelas y labs participantes cuentan con un facilitador, docente, coach o mentor para ayudar a un grupo de estudiantes a participar en el Reto SOD+A, anim\xe1ndolos a iterar, experimentar, compartir y documentar sus creaciones e intentos en nuestro tablero global. Las escuelas y labs participantes tambi\xe9n ayudan a conectar a los estudiantes con oportunidades de co-dise\xf1o donde sus habilidades reci\xe9n descubiertas pueden ponerse en acci\xf3n para marcar una diferencia.",examplesTitle:"El a\xf1o pasado",examples:[{id:"bennett",name:"Bennett"},{id:"sofia",name:"Sofia"},{id:"theo",name:"Theo"},{id:"abby",name:"Abby"}]},glance:{leadTitle:"Aprender a trav\xe9s de las fronteras",lead:"Comparte tu proceso con estudiantes de otras comunidades, rehaz y adapta el trabajo de los dem\xe1s, y construye relaciones haciendo.",fitTitle:"C\xf3mo encaja",fit:"Lleva SOD+A como una actividad cocurricular, una clase, o una colaboraci\xf3n con otra organizaci\xf3n. Tu grupo elige el formato y puede usar los marcos que ya conoce. Los proyectos pueden basarse en el trabajo que los estudiantes ya hacen para otras iniciativas de la escuela.",timelineTitle:"Calendario",timeline:"Cuatro fechas clave entre septiembre y mayo, con plazos, muestras y encuentros de grupo. Pueden ocurrir momentos compartidos m\xe1s peque\xf1os entre medias.",whoTitle:"Qui\xe9n puede unirse",who:"Estudiantes de 14 a 18 a\xf1os que trabajan con una escuela, un espacio de fabricaci\xf3n u otra organizaci\xf3n. No hace falta un Fab Lab. Cualquier nivel de tecnolog\xeda es bienvenido, desde herramientas de mano sencillas hasta cortadoras l\xe1ser y c\xf3digo.",bringTitle:"Escuelas y labs participantes",bring:"Incluye a un facilitador que dirige el grupo, como un docente, un coach o un mentor. Acceso de los estudiantes a computadoras, herramientas o m\xe1quinas de fabricaci\xf3n, y materiales de manualidades. Un proyecto que los estudiantes co-dise\xf1an para generar un impacto. La disposici\xf3n a compartir tu proceso, como un archivo, una receta o una serie de pasos, para que otros puedan rehacer tu trabajo, aprender de \xe9l y adaptarlo. La inversi\xf3n de tiempo suficiente para iterar, responder a los comentarios y mostrar tus esfuerzos.",providesTitle:"SOD+A aporta",provides:"La estructura que las personas facilitadoras necesitan para empezar, incluidas consignas, criterios, buenas pr\xe1cticas y cuatro fechas clave para entregas y comentarios. Un tablero global para compartir, y encuentros regulares del grupo para comparar notas y hacer preguntas. Sin costo para unirse este a\xf1o piloto."},schools:{kicker:"Escuelas y labs participantes"},challenge:{kicker:"\xbfQu\xe9 es el reto?",title:"Mira hasta d\xf3nde puedes empujar una idea",intro:"Puede ser emocionante pensar en algo que te encantar\xeda hacer. A veces no sabes por d\xf3nde empezar, o c\xf3mo usar tus habilidades para contribuir a tu comunidad. De cualquier modo, el reto es convertir ideas en acci\xf3n con sentido. Eso es lo que significa SOD+A, pasar del descubrimiento a la acci\xf3n.",beats:[{title:"Descubre.",detail:"En lugar de un proyecto grande y definido, a\xf1adimos un giro. Trae un inter\xe9s o empieza de cero, deja que las consignas al azar te gu\xeden a un lugar nuevo, experimenta, comparte lo que aprendes y mira qu\xe9 pasa."},{title:"Act\xfaa.",detail:"Ahora tienes ideas nuevas y habilidades nuevas. Ponlas a trabajar con amigos y tu escuela. Trabaja en equipo para llevar un cambio positivo a una comunidad a trav\xe9s del dise\xf1o. Docum\xe9ntalo para que el mundo lo vea."}],closeBefore:"Despl\xe1zate hasta los ",closeLink:"criterios",closeAfter:" para ver hacia d\xf3nde apuntar..."},who:{kicker:"\xbfPara qui\xe9n es?",title:"Estudiantes que quieren crear con otras personas",body:"SOD+A es para estudiantes de 14 a 18 a\xf1os en escuelas, makerspaces o Fab Labs interesados en ingenier\xeda creativa, emprendimiento, dise\xf1o digital y de producto, medios, direcci\xf3n creativa, gesti\xf3n de proyectos, arte y tecnolog\xeda, o cualquier campo en el que importen las ideas, la iniciativa, la colaboraci\xf3n y el compromiso con la comunidad."},why:{kicker:"\xbfPor qu\xe9?",title:"El otro lado de la innovaci\xf3n",p1:"La escuela te da conocimiento, habilidades y estructura. SOD+A te da la experiencia de aprender a trav\xe9s del dise\xf1o y la comunidad. Un descubrimiento colaborativo y pr\xe1ctico, habitual en Fab Labs y universidades, que no siempre encaja en un curr\xedculo de secundaria. Trabajando junto a estudiantes, Fab Labs y universidades m\xe1s all\xe1 de tu propia escuela, profundizar\xe1s m\xe1s en lo que despierta tu curiosidad, usar\xe1s la tecnolog\xeda para hacer algo con sentido, y desarrollar\xe1s las muchas habilidades que el mundo necesita, entre ellas la creatividad, la curiosidad, la resiliencia, el criterio y la colaboraci\xf3n.",p2:"Por el camino, construyes un portafolio que hace visible tu proceso, tus decisiones y tu crecimiento, mientras recibes comentarios y reconocimiento de escuelas y organizaciones colaboradoras que valoran estas habilidades. Es una oportunidad de que te vean, de divertirte, de descubrir lo que puedes hacer y de aprender lo que significa llevar tus talentos al mundo."},criteria:{kicker:"Criterios del reto",title:"Mu\xe9stranos lo que puedes hacer",intro:"Las instituciones colaboradoras marcan los criterios. Cumplirlos abre niveles, logros y certificados mientras experimentas, documentas y compartes."},schedule:{kicker:"Calendario",title:"De septiembre a mayo",intro:"El a\xf1o piloto, marcado en una l\xednea. Descansa sobre un punto para leer esa fecha.",months:["Septiembre","Noviembre","Febrero","Mayo"]},joinForm:{title:"\xdanete al reto",intro:"\xbfQuieres participar en el Reto SOD+A? Completa este formulario:",studentChoice:"Soy estudiante",facilitatorChoice:"Soy facilitador/a",studentIntro:["Los estudiantes recorren el reto guiados por un facilitador, un docente, un coach o un mentor que les ayuda a empezar.","Si te enteraste de este reto y quieres participar, y te gustar\xeda que tu escuela o tus amigos se sumen, completa este formulario y haremos lo posible por ayudarte a formar un grupo o a unirte a uno."],facilitatorIntro:["Reconocemos y celebramos las muchas formas en que escuelas, clubes, labs y organizaciones ya integran el dise\xf1o, el hacer y la creatividad en las experiencias o el curr\xedculo de los j\xf3venes. SOD+A no reemplaza lo que haces; lo amplifica y lo apoya, sumando una comunidad y una plataforma para el intercambio global y la motivaci\xf3n de los estudiantes. Estamos construyendo una red internacional de escuelas, Fab Labs y universidades para alentar el pensamiento divergente y el intercambio entre comunidades, y simplemente queremos unir fuerzas, acercar a los estudiantes a las cosas creativas incre\xedbles que ocurren en el mundo, y retarlos a tomar riesgos creativos y a aprender unos de otros.","Los facilitadores necesitan acceso a un espacio creativo donde los estudiantes puedan compartir trabajo e ideas, pero no necesitas un Fab Lab ni tecnolog\xeda especial. Cuando es posible, podemos ayudarte a encontrar un makerspace o un Fab Lab, o trabajar contigo para planear e integrar SOD+A en tu contexto actual. En resumen, queremos energ\xeda creativa, curiosidad y colaboraci\xf3n por encima de la complejidad y de grandes instalaciones llenas de tecnolog\xeda. Podemos acompa\xf1arte en la estructura y el ritmo del Reto SOD+A sin importar cu\xe1ntos recursos tengas a mano, pero lo que m\xe1s importa es la parte humana."],submit:"Enviar",sending:"Enviando…",thanks:"Gracias. Nos pondremos en contacto.",error:"No se pudo enviar. Int\xe9ntalo de nuevo, o escribe a hello@sodachallenge.org.",activate:"Revisa Gmail, abre el correo de FormSubmit, pulsa Activate Form y vuelve a enviar.",back:"Volver al reto",name:"Nombre",email:"Correo",age:"Edad",schoolLevel:"Nivel escolar",schoolOrg:"Escuela u organizaci\xf3n",guideName:"Nombre de un profesor o profesional que pueda guiarte",guideEmail:"Su correo",interests:"Intereses",orgName:"Nombre de la organizaci\xf3n",role:"Rol",studentAges:"Edad del estudiantado con el que trabajas",facilities:"Instalaciones a las que tienes acceso",expertise:"\xbfQu\xe9 experiencia hay en tu organizaci\xf3n que pueda ayudar?",questions:"\xbfAlguna pregunta sobre el reto?",hours:"\xbfCu\xe1ntas horas a la semana puedes dedicar a esta actividad?"},ask:{kicker:"El panorama general",paragraphs:["Nuestra meta es hacer crecer SOD+A como una vitrina internacional que celebra la acci\xf3n de los estudiantes hacia la creatividad, la curiosidad y la colaboraci\xf3n. Queremos retar a los estudiantes a participar en el tipo de experiencias que construyen estas habilidades, y ofrecer comentarios reales del mundo que las necesita.","Actualmente, el SOD+A Challenge es un concepto en acci\xf3n. Probamos la idea el a\xf1o pasado con dos escuelas y dos aliados, y vimos a los estudiantes entusiasmarse por experimentar, iterar, compartir y actuar sobre sus ideas a trav\xe9s del dise\xf1o. Ahora miramos un segundo a\xf1o piloto para ampliar esto, y estamos co-dise\xf1ando la experiencia con nuestros participantes y aliados."]},reach:{mapLabel:"Mapa del mundo de Schools of Discovery + Action",cities:{montreal:"Montreal",barcelona:"Barcelona",toronto:"Toronto",calgary:"Calgary",monterey:"Monterey"},places:{montreal:"Lower Canada College",barcelona:"Fab Lab Barcelona",toronto:"OCAD University",calgary:"",monterey:"M\xe9xico"}}}}},9915:(e,a,o)=>{o.d(a,{I:()=>s,o:()=>l});var t=o(5155),n=o(2115),i=o(9902);let r=(0,n.createContext)(null);function s(e){let{children:a}=e,[o,s]=(0,n.useState)("en");(0,n.useEffect)(()=>{var e,a;s(null!=(e=function(){try{let e=window.localStorage.getItem(i.zl);return(0,i.Zd)(e)?e:null}catch(e){return null}}())?e:(0,i.pg)("undefined"==typeof navigator?[]:(null==(a=navigator.languages)?void 0:a.length)?navigator.languages:navigator.language?[navigator.language]:[]))},[]),(0,n.useEffect)(()=>{document.documentElement.lang=o;let e=document.querySelector('meta[name="description"]');e&&e.setAttribute("content",i.C[o].metaDescription)},[o]);let l=(0,n.useCallback)(e=>{s(e);try{window.localStorage.setItem(i.zl,e)}catch(e){}},[]),c=(0,n.useMemo)(()=>({locale:o,setLocale:l,t:i.C[o]}),[o,l]);return(0,t.jsx)(r.Provider,{value:c,children:a})}function l(){let e=(0,n.useContext)(r);if(!e)throw Error("useLanguage must be used within LanguageProvider");return e}}}]);